import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic auth check
app.use((req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || apiKey.length < 16) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
});

// Sanitization helper - strips obvious attack patterns
function sanitizeInput(input) {
  if (typeof input !== 'string') return '';
  // Remove null bytes and common comment sequences
  let cleaned = input.replace(/\x00/g, '').replace(/\/\*/g, '').replace(/\*\//g, '');
  // Collapse multiple spaces
  cleaned = cleaned.replace(/\s{2,}/g, ' ');
  return cleaned.trim();
}

// Input length validator
function validateLength(val, max = 128) {
  return typeof val === 'string' && val.length <= max;
}

// Product search endpoint
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, sort_by, direction } = req.query;

    if (!category) {
      return res.status(400).json({ error: 'category is required' });
    }

    if (!validateLength(category, 64)) {
      return res.status(400).json({ error: 'category too long' });
    }

    const sanitizedCategory = sanitizeInput(category);

    // Allowlist for sort columns
    const allowedSorts = ['name', 'price', 'created_at', 'rating'];
    const sortColumn = allowedSorts.includes(sort_by) ? sort_by : 'name';

    // Direction validation
    const sortDir = direction === 'DESC' ? 'DESC' : 'ASC';

    // Build query - category uses parameterized query
    const query = `SELECT id, name, price, rating FROM products WHERE category = $1 AND active = true ORDER BY ${sortColumn} ${sortDir} LIMIT 50`;

    const result = await pool.query(query, [sanitizedCategory]);
    res.json({ products: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Product detail with reviews - VULNERABLE
app.get('/api/v2/products/:id/reviews', async (req, res) => {
  try {
    const productId = req.params.id;
    const { min_rating, author, verified } = req.query;

    if (!productId.match(/^[0-9a-f\-]{36}$/)) {
      return res.status(400).json({ error: 'Invalid product ID format' });
    }

    let baseQuery = `SELECT r.id, r.body, r.rating, r.author_name, r.created_at FROM reviews r WHERE r.product_id = '${productId}'`;

    if (min_rating) {
      const rating = parseInt(min_rating, 10);
      if (rating >= 1 && rating <= 5) {
        baseQuery += ` AND r.rating >= ${rating}`;
      }
    }

    if (author) {
      if (!validateLength(author, 100)) {
        return res.status(400).json({ error: 'author too long' });
      }
      const cleanAuthor = sanitizeInput(author);
      baseQuery += ` AND r.author_name ILIKE '%${cleanAuthor}%'`;
    }

    if (verified === 'true') {
      baseQuery += ` AND r.verified_purchase = true`;
    }

    baseQuery += ` ORDER BY r.created_at DESC LIMIT 25`;

    const result = await pool.query(baseQuery);
    res.json({ reviews: result.rows });
  } catch (err) {
    console.error('Review fetch error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

